import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"皇矣","description":"","frontmatter":{"title":"皇矣","date":"2026-11-09T00:00:00.000Z","seq":7,"categories":["美文","诗经"],"collection":"《诗经 · 大雅》","tags":["诗经","先秦"],"poem":true,"author":"佚名","source_book":"诗经"},"headers":[],"relativePath":"blogs/诗经·大雅/皇矣.md","filePath":"blogs/诗经·大雅/皇矣.md"}'),o={name:"blogs/诗经·大雅/皇矣.md"};function c(l,a,n,m,r,_){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="皇矣" tabindex="-1">皇矣 <a class="header-anchor" href="#皇矣" aria-label="Permalink to &quot;皇矣&quot;">​</a></h1><p class="poem-meta">先秦 · 佚名　·　文王之什</p><div class="poem"><p class="poem-stanza">皇矣上帝，临下有赫。监观四方，求民之莫。维此二国，其政不获。</p><p class="poem-stanza">维彼四国，爰究爰度。上帝耆之，憎其式廓。乃眷西顾，此维与宅。</p><p class="poem-stanza">作之屏之，其菑其翳。修之平之，其灌其栵。启之辟之，其柽其椐。</p><p class="poem-stanza">攘之剔之，其檿其柘。帝迁明德，串夷载路。天立厥配，受命既固。</p><p class="poem-stanza">帝省其山，柞棫斯拔，松柏斯兑。帝作邦作对，自大伯王季。维此王季，</p><p class="poem-stanza">因心则友。则友其兄，则笃其庆，载锡之光。受禄无丧，奄有四方。</p><p class="poem-stanza">维此王季，帝度其心。貊其德音，其德克明。克明克类，克长克君。</p><p class="poem-stanza">王此大邦，克顺克比。比于文王，其德靡悔。既受帝祉，施于孙子。</p><p class="poem-stanza">帝谓文王：无然畔援，无然歆羡，诞先登于岸。密人不恭，敢距大邦，</p><p class="poem-stanza">侵阮徂共。王赫斯怒，爰整其旅，以按徂旅。以笃于周祜，以对于天下。</p><p class="poem-stanza">依其在京，侵自阮疆。陟我高冈，无矢我陵。我陵我阿，无饮我泉，</p><p class="poem-stanza">我泉我池。度其鲜原，居岐之阳，在渭之将。万邦之方，下民之王。</p><p class="poem-stanza">帝谓文王：予怀明德，不大声以色，不长夏以革。不识不知，顺帝之则。</p><p class="poem-stanza">帝谓文王：訽尔仇方，同尔弟兄。以尔钩援，与尔临冲，以伐崇墉。</p><p class="poem-stanza">临冲闲闲，崇墉言言。执讯连连，攸馘安安。是类是禡，是致是附，</p><p class="poem-stanza">四方以无侮。临冲茀茀，崇墉仡仡。是伐是四，是绝是忽。四方以无拂。</p></div>',3)])])}const z=s(o,[["render",c]]);export{d as __pageData,z as default};
